class Solution:
    def atMostNGivenDigitSet(self, digits, n: int) -> int:
        s = str(n)
        k, d = len(s), len(digits)
        res = sum(d**i for i in range(1, k))
        for i, c in enumerate(s):
            less = sum(1 for x in digits if x < c)
            res += less * (d ** (k - i - 1))
            if c not in digits:
                break
            if i == k - 1:
                res += 1
        return res

