class Solution:
    def sumSubarrayMins(self, arr) -> int:
        MOD = 10**9 + 7
        n = len(arr)
        left, right = [0]*n, [0]*n
        stk = []
        for i in range(n):
            while stk and arr[stk[-1]] >= arr[i]:
                stk.pop()
            left[i] = i - stk[-1] if stk else i + 1
            stk.append(i)
        stk = []
        for i in range(n-1, -1, -1):
            while stk and arr[stk[-1]] > arr[i]:
                stk.pop()
            right[i] = stk[-1] - i if stk else n - i
            stk.append(i)
        return sum(arr[i]*left[i]*right[i] for i in range(n)) % MOD

