    def catMouseGame(self, graph) -> int:
        from collections import deque
        n = len(graph)
        DRAW, MOUSE, CAT = 0, 1, 2
        color = [[[DRAW]*3 for _ in range(n)] for _ in range(n)]
        degree = [[[0]*3 for _ in range(n)] for _ in range(n)]
        for m in range(n):
            for c in range(n):
                degree[m][c][1] = len(graph[m])
                degree[m][c][2] = len(graph[c]) - (0 in graph[c])
        q = deque()
        for i in range(n):
            for t in (1, 2):
                color[0][i][t] = MOUSE
                q.append((0, i, t, MOUSE))
                if i > 0:
                    color[i][i][t] = CAT
                    q.append((i, i, t, CAT))
        while q:
            m, c, t, result = q.popleft()
            for pm, pc, pt in self.parents(graph, m, c, t, n):
                if color[pm][pc][pt] != DRAW: continue
                if pt == result:
                    color[pm][pc][pt] = result
                    q.append((pm, pc, pt, result))
                else:
                    degree[pm][pc][pt] -= 1
                    if degree[pm][pc][pt] == 0:
                        color[pm][pc][pt] = result
                        q.append((pm, pc, pt, result))
