class Solution:
    def threeSumMulti(self, arr, target):
        from collections import Counter
        c = Counter(arr)
        keys = sorted(c)
        res = 0
        MOD = 10**9 + 7
        for i, x in enumerate(keys):
            for y in keys[i:]:
                z = target - x - y
                if z < y: break
                if z not in c: continue
                if x == y == z:
                    res += c[x] * (c[x]-1) * (c[x]-2) // 6
                elif x == y:
                    res += c[x] * (c[x]-1) // 2 * c[z]
