class Solution:
    def movesToStamp(self, stamp, target):
        s, t = list(stamp), list(target)
        m, n = len(s), len(t)
        res = []
        total = 0
        while total < n:
            found = False
            for i in range(n - m + 1):
                matched = replaced = 0
                for j in range(m):
                    if t[i+j] == '?': replaced += 1
                    elif t[i+j] == s[j]: matched += 1
