class Solution:
    def shortestSuperstring(self, words):
        n = len(words)
        overlap = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    for k in range(min(len(words[i]), len(words[j])), 0, -1):
                        if words[i][-k:] == words[j][:k]:
                            overlap[i][j] = k
                            break
        dp = [[0]*n for _ in range(1<<n)]
        parent = [[-1]*n for _ in range(1<<n)]
        for mask in range(1<<n):
            for i in range(n):
                if not (mask & (1<<i)): continue
                pmask = mask ^ (1<<i)
                if pmask == 0: continue
                for j in range(n):
                    if not (pmask & (1<<j)): continue
                    val = dp[pmask][j] + overlap[j][i]
                    if val > dp[mask][i]:
                        dp[mask][i] = val
                        parent[mask][i] = j
        full = (1<<n) - 1
        last = max(range(n), key=lambda i: dp[full][i])
        order = []
        mask = full
        while last != -1:
            order.append(last)
            p = parent[mask][last]
            mask ^= (1<<last)
            last = p
        order.reverse()
        res = words[order[0]]
        for i in range(1, len(order)):
            ov = overlap[order[i-1]][order[i]]
            res += words[order[i]][ov:]
        return res

