class Solution:
    def bagOfTokensScore(self, tokens, power):
        tokens.sort()
        lo, hi = 0, len(tokens)-1
        score = res = 0
        while lo <= hi:
            if power >= tokens[lo]:
                power -= tokens[lo]
                lo += 1
                score += 1
                res = max(res, score)
            elif score > 0:
                power += tokens[hi]
                hi -= 1
                score -= 1
            else:
                break
        return res

