        for r in rods:
            ndp = dict(dp)
            for d, tall in dp.items():
                ndp[d+r] = max(ndp.get(d+r, 0), tall)
                ndp[abs(d-r)] = max(ndp.get(abs(d-r), 0), tall + min(d, r))
            dp = ndp
        return dp[0]

class Solution:
    def prisonAfterNDays(self, cells, n):
        seen = {}
        while n > 0:
            state = tuple(cells)
            if state in seen:
                cycle = seen[state] - n
                n %= cycle
            seen[state] = n
            if n > 0:
                cells = [0] + [int(cells[i-1] == cells[i+1]) for i in range(1, 7)] + [0]
                n -= 1
        return cells

class Solution:
    def isCompleteTree(self, root):
        from collections import deque
        q = deque([root])
        end = False
        while q:
            node = q.popleft()
            if not node:
                end = True
            else:
                if end: return False
                q.append(node.left)
                q.append(node.right)
        return True

class Solution:
    def regionsBySlashes(self, grid):
        n = len(grid)
        parent = list(range(4*n*n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            parent[find(a)] = find(b)
        for i in range(n):
            for j in range(n):
                base = 4*(i*n+j)
                if grid[i][j] == ' ':
                    union(base,base+1)
                    union(base+1,base+2)
                    union(base+2,base+3)
                elif grid[i][j] == '/':
                    union(base,base+3)
                    union(base+1,base+2)
                else:
                    union(base,base+1)
                    union(base+2,base+3)
                if j+1<n: union(base+1,4*(i*n+j+1)+3)
                if i+1<n: union(base+2,4*((i+1)*n+j))
        return len(set(find(x) for x in range(4*n*n)))

class Solution:
    def minDeletionSize(self, strs):
        n, m = len(strs), len(strs[0])
        dp = [1] * m
        for j in range(1, m):
            for i in range(j):
                if all(strs[r][i] <= strs[r][j] for r in range(n)):
                    dp[j] = max(dp[j], dp[i] + 1)
        return m - max(dp)
